    });
    defer req.deinit();
    req.transfer_encoding = .{ .content_length = payload.len };
    try req.send();
    try req.writeAll(payload);
    try req.finish();
    try req.wait();
    var read_buf: [8192]u8 = undefined;
    const stdout = std.io.getStdOut().writer();
    while (true) {
        const len = try req.read(&read_buf);
        if (len == 0) break;
        try stdout.writeAll(read_buf[0..len]);
    }
}

